volcano_caldera_lake.source:
export const envelope = [48, 32, 48];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 6;
  const cx = 24.0;
  const cz = 25.0;

  // Palette from world theme with fallback to volcanic minerals
  const stonePrimary = api.theme.stone.primary || "minecraft:blackstone";
  const stoneAccent = api.theme.stone.accent || "minecraft:polished_blackstone";
  const stoneWall = api.theme.stone.wall || "minecraft:blackstone_wall";
  const stoneSlab = api.theme.stone.slab || "minecraft:blackstone_slab";
  const groundScree = api.theme.ground.scree || "minecraft:basalt";
  const groundPavement = api.theme.ground.pavement || "minecraft:smooth_basalt";
  const groundPlinth = api.theme.ground.plinth || "minecraft:polished_blackstone";

  // Specialized volcanic blocks
  const B_BASALT_Y = "minecraft:basalt[axis=y]";
  const B_POL_BASALT_Y = "minecraft:polished_basalt[axis=y]";
  const B_SMOOTH_BASALT = "minecraft:smooth_basalt";
  const B_BLACKSTONE = "minecraft:blackstone";
  const B_MAGMA = "minecraft:magma_block";
  const B_SHROOMLIGHT = "minecraft:shroomlight";
  const B_CRYING_OBSIDIAN = "minecraft:crying_obsidian";
  const B_OBSIDIAN = "minecraft:obsidian";
  const B_GILDED_BLACKSTONE = "minecraft:gilded_blackstone";
  const B_BLACKSTONE_WALL = stoneWall;
  const B_BLACKSTONE_SLAB = stoneSlab;
  const B_POL_SLAB = "minecraft:polished_blackstone_slab[type=bottom]";
  const B_CAMPFIRE = "minecraft:campfire[facing=north,lit=true]";

  // 3D Voxel buffer
  const grid = new Array(W * H * D);

  function getVoxel(x, y, z) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return null;
    return grid[x + W * (y + H * z)] || null;
  }

  function setVoxel(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x + W * (y + H * z)] = block;
    }
  }

  // Deterministic seedable 2D noise generator
  const seedVal = Math.floor(api.random() * 65536);
  const perm = new Uint8Array(512);
  let s = (seedVal + 1337) & 0xffff;
  for (let i = 0; i < 256; i++) {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    perm[i] = (s >> 16) & 255;
  }
  for (let i = 0; i < 256; i++) perm[256 + i] = perm[i];

  function noise2D(x, z) {
    const X = Math.floor(x) & 255;
    const Z = Math.floor(z) & 255;
    const xf = x - Math.floor(x);
    const zf = z - Math.floor(z);
    const u = xf * xf * (3 - 2 * xf);
    const v = zf * zf * (3 - 2 * zf);

    const a = perm[X] + Z;
    const b = perm[X + 1] + Z;

    const g00 = ((perm[a] & 1) === 0 ? xf : -xf) + ((perm[a] & 2) === 0 ? zf : -zf);
    const g10 = ((perm[b] & 1) === 0 ? xf - 1 : -(xf - 1)) + ((perm[b] & 2) === 0 ? zf : -zf);
    const g01 = ((perm[a + 1] & 1) === 0 ? xf : -xf) + ((perm[a + 1] & 2) === 0 ? zf - 1 : -(zf - 1));
    const g11 = ((perm[b + 1] & 1) === 0 ? xf - 1 : -(xf - 1)) + ((perm[b + 1] & 2) === 0 ? zf - 1 : -(zf - 1));

    const x1 = g00 + u * (g10 - g00);
    const x2 = g01 + u * (g11 - g01);
    return x1 + v * (x2 - x1);
  }

  function normalizeAngle(a) {
    while (a > Math.PI) a -= 2 * Math.PI;
    while (a < -Math.PI) a += 2 * Math.PI;
    return a;
  }

  function getRimRadius(theta) {
    return 15.2 + 1.8 * Math.sin(3 * theta + 0.5) + 1.2 * Math.cos(5 * theta - 0.3) + 0.7 * Math.sin(2 * theta);
  }

  function getBaseRadius(theta) {
    return getRimRadius(theta) + 6.8 + 1.4 * Math.cos(4 * theta + 0.8);
  }

  function getRimHeight(theta) {
    let h = 15.2 + 2.4 * Math.sin(2 * theta - 0.4) + 1.5 * Math.cos(3 * theta + 0.8);
    const dTheta = Math.abs(normalizeAngle(theta - (-Math.PI / 2)));
    const breachWidth = 0.46;
    if (dTheta < breachWidth) {
      const t = dTheta / breachWidth;
      const ease = 0.5 - 0.5 * Math.cos(t * Math.PI);
      h = 6.8 + (h - 6.8) * ease;
    }
    return Math.min(20, Math.max(6.5, h));
  }

  function riverCenterX(z) {
    return 24.0 + 1.8 * Math.sin(z * 0.28) + 0.7 * Math.cos(z * 0.55);
  }

  function distToSegmentSq(px, pz, x1, z1, x2, z2) {
    const dx = x2 - x1;
    const dz = z2 - z1;
    const l2 = dx * dx + dz * dz;
    if (l2 === 0) return (px - x1) * (px - x1) + (pz - z1) * (pz - z1);
    let t = ((px - x1) * dx + (pz - z1) * dz) / l2;
    t = Math.max(0, Math.min(1, t));
    const projX = x1 + t * dx;
    const projZ = z1 + t * dz;
    return (px - projX) * (px - projX) + (pz - projZ) * (pz - projZ);
  }

  // Precompute ground heights
  const groundMap = new Int16Array(W * D);
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const rawH = api.heightAt(x, z);
      groundMap[x + W * z] = Math.max(0, Math.min(22, seatY + Math.round(rawH)));
    }
  }

  const riverMouthGround = groundMap[24 + W * 0];

  // Pass 1: Build the primary caldera mountain, crater bowl, and outer flanks
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const r = Math.sqrt(dx * dx + dz * dz);
      const theta = Math.atan2(dz, dx);

      const rRim = getRimRadius(theta);
      const rBase = getBaseRadius(theta);
      const hRim = getRimHeight(theta);
      const rLake = rRim - 3.8;
      const colGround = groundMap[x + W * z];

      let colTopY = colGround;
      let isInsideCrater = false;
      let isLake = false;

      if (r <= rLake && z > 15) {
        colTopY = seatY + 9;
        isInsideCrater = true;
        isLake = true;
      } else if (r <= rRim) {
        const u = Math.max(0, Math.min(1, (r - rLake) / Math.max(0.1, rRim - rLake)));
        const innerH = seatY + 9 + (hRim - 9) * Math.pow(u, 1.35);
        colTopY = Math.round(innerH);
        isInsideCrater = true;
      } else if (r <= rBase) {
        const u = Math.max(0, Math.min(1, (rBase - r) / Math.max(0.1, rBase - rRim)));
        const flankH = colGround + (hRim - (colGround - seatY)) * Math.pow(u, 1.25);
        colTopY = Math.round(flankH + noise2D(x * 0.18, z * 0.18) * 1.6);
      } else {
        colTopY = colGround;
      }

      // Carve Northern Lava River Breach and Gorge
      let isRiverStream = false;
      let isRiverBed = false;
      let riverBedY = seatY;
      let riverSurfY = seatY + 1;

      if (z <= 20) {
        const rx = riverCenterX(z);
        const distRivX = Math.abs(x - rx);
        const wRiv = 2.2 + 1.2 * (1.0 - z / 20.0);
        const wGorge = wRiv + 3.2;

        const tZ = Math.max(0, Math.min(1, z / 18.0));
        const mouthY = riverMouthGround;
        riverBedY = Math.round(mouthY + (seatY + 8 - mouthY) * Math.pow(tZ, 1.15));
        riverSurfY = Math.min(seatY + 9, riverBedY + 1);

        if (distRivX <= wRiv) {
          colTopY = riverSurfY;
          isRiverStream = true;
        } else if (distRivX <= wGorge) {
          const v = (distRivX - wRiv) / (wGorge - wRiv);
          const gorgeWallY = riverSurfY + (colTopY - riverSurfY) * Math.pow(v, 0.7);
          colTopY = Math.min(colTopY, Math.round(gorgeWallY));
        }
      }

      // Check for Glowing Magma Fissures/Dykes on outer flanks
      const dDyke1 = Math.sqrt(distToSegmentSq(x, z, 27, 30, 41, 42));
      const dDyke2 = Math.sqrt(distToSegmentSq(x, z, 21, 30, 7, 41));
      const dDyke3 = Math.sqrt(distToSegmentSq(x, z, 15, 25, 4, 25));
      const minDykeDist = Math.min(dDyke1, dDyke2, dDyke3);
      const isDyke = !isLake && !isRiverStream && r > rRim && minDykeDist < 1.35;

      // Fill Column from Ground/Foundation up to Top
      const bottomY = Math.min(colGround, seatY);
      for (let y = bottomY; y <= colTopY; y++) {
        if (y < colGround) {
          // Sub-terrain foundation skirt
          setVoxel(x, y, z, y === bottomY ? groundPlinth : groundScree);
        } else if (isRiverStream) {
          if (y === riverBedY) {
            setVoxel(x, y, z, (x + z) % 3 === 0 ? B_CRYING_OBSIDIAN : B_MAGMA);
          } else if (y === riverSurfY) {
            const centerDist = Math.abs(x - riverCenterX(z));
            if (centerDist < 0.9) {
              setVoxel(x, y, z, (z % 3 === 0) ? B_SHROOMLIGHT : B_MAGMA);
            } else {
              setVoxel(x, y, z, (x + z) % 4 === 0 ? B_SMOOTH_BASALT : B_MAGMA);
            }
          } else {
            setVoxel(x, y, z, stonePrimary);
          }
        } else if (isLake && y === seatY + 9) {
          // Lake surface handled in Pass 2
          setVoxel(x, y, z, B_MAGMA);
        } else if (isLake && y === seatY + 8) {
          setVoxel(x, y, z, (x * 7 + z * 13) % 5 === 0 ? B_CRYING_OBSIDIAN : B_MAGMA);
        } else if (isDyke && y >= colTopY - 1) {
          if (minDykeDist < 0.65) {
            setVoxel(x, y, z, (x + y + z) % 4 === 0 ? B_SHROOMLIGHT : B_MAGMA);
          } else {
            setVoxel(x, y, z, B_CRYING_OBSIDIAN);
          }
        } else if (y === colTopY) {
          // Top surface decoration
          if (r > rRim - 1.5 && r < rRim + 1.5) {
            // Rim Crest Columnar Basalt
            setVoxel(x, y, z, (x + z) % 2 === 0 ? B_POL_BASALT_Y : B_BASALT_Y);
            // Occasional organ pipe vertical columns extending 1 block higher
            if ((x * 3 + z * 5) % 7 === 0 && colTopY + 1 < H - 2) {
              setVoxel(x, colTopY + 1, z, B_BASALT_Y);
              if ((x + z) % 3 === 0) {
                setVoxel(x, colTopY + 2, z, B_POL_SLAB);
              }
            }
          } else {
            const surfNoise = noise2D(x * 0.35, z * 0.35);
            if (surfNoise > 0.35) {
              setVoxel(x, y, z, B_GILDED_BLACKSTONE);
            } else if (surfNoise > 0.0) {
              setVoxel(x, y, z, B_SMOOTH_BASALT);
            } else if (surfNoise > -0.35) {
              setVoxel(x, y, z, stonePrimary);
            } else {
              setVoxel(x, y, z, groundScree);
            }
          }
        } else if (y >= colTopY - 2) {
          setVoxel(x, y, z, (x + z) % 2 === 0 ? B_BASALT_Y : stonePrimary);
        } else {
          setVoxel(x, y, z, stonePrimary);
        }
      }
    }
  }

  // Pass 2: Magma Lake Convection Currents and Crusted Basalt Rafts
  const lakeY = seatY + 9;
  for (let x = 0; x < W; x++) {
    for (let z = 16; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const r = Math.sqrt(dx * dx + dz * dz);
      const theta = Math.atan2(dz, dx);
      const rRim = getRimRadius(theta);
      const rLake = rRim - 3.8;

      if (r <= rLake) {
        // Swirling magma fissure convection formula
        const f = Math.sin(r * 0.72 - theta * 3.0) + noise2D(x * 0.35, z * 0.35) * 1.3;

        if (Math.abs(f) < 0.22) {
          // Searing core fissure
          setVoxel(x, lakeY, z, B_SHROOMLIGHT);
          setVoxel(x, lakeY - 1, z, B_MAGMA);
        } else if (Math.abs(f) < 0.52) {
          // Glowing magma stream
          setVoxel(x, lakeY, z, B_MAGMA);
          setVoxel(x, lakeY - 1, z, (x + z) % 2 === 0 ? B_MAGMA : B_CRYING_OBSIDIAN);
        } else {
          // Crusted Basalt Raft Plate
          const crustChoice = (x * 11 + z * 17) % 6;
          if (crustChoice === 0) setVoxel(x, lakeY, z, B_SMOOTH_BASALT);
          else if (crustChoice === 1) setVoxel(x, lakeY, z, B_BASALT_Y);
          else if (crustChoice === 2) setVoxel(x, lakeY, z, B_POL_BASALT_Y);
          else if (crustChoice === 3) setVoxel(x, lakeY, z, B_GILDED_BLACKSTONE);
          else setVoxel(x, lakeY, z, B_BLACKSTONE);

          // Raised crust plate center slab
          if (Math.abs(f) > 0.95 && r < rLake - 1.2) {
            setVoxel(x, lakeY + 1, z, B_BLACKSTONE_SLAB);
          }
        }
      }
    }
  }

  // Pass 3: Procedural Volcanic Vent Horns, Chimneys, and Fumaroles

  // Horn 1: The Great Summit Magma Chimney (Center South)
  const h1x = 24;
  const h1z = 30;
  for (let y = lakeY; y <= lakeY + 7; y++) {
    const dy = y - lakeY;
    const rad = 2.4 - dy * 0.25;
    for (let ox = -3; ox <= 3; ox++) {
      for (let oz = -3; oz <= 3; oz++) {
        const distSq = ox * ox + oz * oz;
        const d = Math.sqrt(distSq);
        const px = h1x + ox;
        const pz = h1z + oz;
        if (d <= rad) {
          if (d < 0.85) {
            if (y <= lakeY + 4) {
              setVoxel(px, y, pz, B_SHROOMLIGHT);
            } else if (y === lakeY + 5) {
              setVoxel(px, y, pz, B_MAGMA);
            } else if (y === lakeY + 6) {
              setVoxel(px, y, pz, B_CAMPFIRE); // Summit smoke plume
            }
          } else {
            // Chimney walls
            if (y === lakeY + 7) {
              if ((ox + oz) % 2 === 0) setVoxel(px, y, pz, B_BLACKSTONE_WALL);
            } else if (y >= lakeY + 5) {
              setVoxel(px, y, pz, (ox * 3 + oz * 5 + y) % 2 === 0 ? B_CRYING_OBSIDIAN : B_OBSIDIAN);
            } else {
              setVoxel(px, y, pz, (ox + oz) % 3 === 0 ? B_CRYING_OBSIDIAN : B_BLACKSTONE);
            }
          }
        }
      }
    }
  }
  // Chimney north face magma cascade
  setVoxel(24, lakeY + 1, 28, B_MAGMA);
  setVoxel(24, lakeY + 2, 28, B_SHROOMLIGHT);
  setVoxel(24, lakeY + 3, 28, B_MAGMA);

  // Horn 2: Crying Obsidian Spire (East)
  const h2x = 29;
  const h2z = 23;
  for (let y = lakeY; y <= lakeY + 4; y++) {
    const dy = y - lakeY;
    const rad = 1.6 - dy * 0.25;
    for (let ox = -2; ox <= 2; ox++) {
      for (let oz = -2; oz <= 2; oz++) {
        const d = Math.sqrt(ox * ox + oz * oz);
        if (d <= rad) {
          const px = h2x + ox;
          const pz = h2z + oz;
          if (y === lakeY + 4) {
            setVoxel(px, y, pz, B_BLACKSTONE_WALL);
          } else if (d < 0.7 && y === lakeY + 3) {
            setVoxel(px, y, pz, B_MAGMA);
          } else {
            setVoxel(px, y, pz, (ox + oz + y) % 2 === 0 ? B_CRYING_OBSIDIAN : B_GILDED_BLACKSTONE);
          }
        }
      }
    }
  }

  // Horn 3: Bubbling Horn & Lake Vent (West)
  const h3x = 19;
  const h3z = 24;
  for (let y = lakeY; y <= lakeY + 3; y++) {
    const dy = y - lakeY;
    const rad = 1.5 - dy * 0.3;
    for (let ox = -2; ox <= 2; ox++) {
      for (let oz = -2; oz <= 2; oz++) {
        const d = Math.sqrt(ox * ox + oz * oz);
        if (d <= rad) {
          const px = h3x + ox;
          const pz = h3z + oz;
          if (y === lakeY + 3) {
            setVoxel(px, y, pz, B_BLACKSTONE_WALL);
          } else if (d < 0.6 && y === lakeY + 2) {
            setVoxel(px, y, pz, B_SHROOMLIGHT);
          } else {
            setVoxel(px, y, pz, (ox + y) % 2 === 0 ? B_OBSIDIAN : B_MAGMA);
          }
        }
      }
    }
  }

  // Rim Fumaroles (Smoking vents on outer crest)
  function buildFumarole(fx, fz) {
    let topY = groundMap[fx + W * fz];
    for (let y = H - 1; y >= 0; y--) {
      if (getVoxel(fx, y, fz) !== null) {
        topY = y;
        break;
      }
    }
    if (topY < H - 3) {
      setVoxel(fx, topY, fz, B_MAGMA);
      setVoxel(fx, topY + 1, fz, B_CAMPFIRE);
      setVoxel(fx + 1, topY + 1, fz, B_BLACKSTONE_WALL);
      setVoxel(fx - 1, topY + 1, fz, B_BLACKSTONE_WALL);
      setVoxel(fx, topY + 1, fz + 1, B_BLACKSTONE_WALL);
      setVoxel(fx, topY + 1, fz - 1, B_BLACKSTONE_WALL);
    }
  }
  buildFumarole(35, 27);
  buildFumarole(13, 27);

  // Pass 4: Gorge Boulders, Basalt Wall Spires, and Lava Edge Overhangs
  for (let z = 2; z <= 17; z++) {
    const rx = riverCenterX(z);
    const wRiv = 2.2 + 1.2 * (1.0 - z / 20.0);

    // Left bank boulder/wall
    const lbX = Math.round(rx - wRiv - 0.7);
    const rbX = Math.round(rx + wRiv + 0.7);

    for (const bx of [lbX, rbX]) {
      if (bx >= 0 && bx < W) {
        for (let y = H - 1; y >= seatY; y--) {
          if (getVoxel(bx, y, z) !== null) {
            if ((bx * 7 + z * 11) % 5 === 0 && y + 1 < H - 2) {
              setVoxel(bx, y + 1, z, B_BLACKSTONE_WALL);
            } else if ((bx + z) % 4 === 0 && y + 1 < H - 2) {
              setVoxel(bx, y + 1, z, B_POL_SLAB);
            }
            break;
          }
        }
      }
    }
  }

  // Pass 5: Ground Conformity Skirt Guarantee
  // Ensure every occupied column is solidly grounded down to heightAt(x, z)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const gH = groundMap[x + W * z];
      // Find lowest non-null voxel in column
      let lowestY = -1;
      let highestY = -1;
      for (let y = 0; y < H; y++) {
        if (getVoxel(x, y, z) !== null) {
          if (lowestY === -1) lowestY = y;
          highestY = y;
        }
      }

      if (lowestY !== -1) {
        // Fill downwards if floating above real terrain
        if (gH < lowestY) {
          for (let y = gH; y < lowestY; y++) {
            setVoxel(x, y, z, y === gH ? groundPlinth : groundScree);
          }
        }
        // If terrain is higher than lowestY, fill upwards solid to avoid internal hollows
        if (gH > lowestY) {
          for (let y = lowestY; y <= Math.min(gH, highestY); y++) {
            if (getVoxel(x, y, z) === null) {
              setVoxel(x, y, z, stonePrimary);
            }
          }
        }
      }
    }
  }

  // Emit all voxels to the world API
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[x + W * (y + H * z)];
        if (block) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Volcano Caldera Lake",
    seatY: seatY,
    anchors: {
      front: [24, riverMouthGround, 0],
      summit: [24, seatY + 16, 30],
    },
  };
}

