export const envelope = [20, 11, 16];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 3;
  const rng = () => api.random();
  const idx = api.instance.index % 8;

  // 1. Grid representation for geometry & connectivity
  const grid = new Map();
  function key(x, y, z) {
    return `${x},${y},${z}`;
  }
  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid.set(key(x, y, z), block);
    }
  }
  function get(x, y, z) {
    return grid.get(key(x, y, z)) || null;
  }
  function has(x, y, z) {
    return grid.has(key(x, y, z));
  }

  // 2. Palette from theme with volcanic rock defaults
  const stonePrimary = api.theme.stone.primary || "minecraft:blackstone";
  const stoneSlab = api.theme.stone.slab || "minecraft:blackstone_slab";
  const stoneStairs = api.theme.stone.stairs || "minecraft:blackstone_stairs";
  const stoneWall = api.theme.stone.wall || "minecraft:blackstone_wall";
  const scree = api.theme.ground.scree || "minecraft:basalt[axis=y]";
  const smoothBasalt = "minecraft:smooth_basalt";
  const basaltY = "minecraft:basalt[axis=y]";
  const basaltX = "minecraft:basalt[axis=x]";
  const basaltZ = "minecraft:basalt[axis=z]";
  const polishedBasalt = "minecraft:polished_basalt[axis=y]";
  const blackstone = "minecraft:blackstone";
  const magma = "minecraft:magma_block";
  const obsidian = "minecraft:obsidian";
  const cryingObsidian = "minecraft:crying_obsidian";
  const shroomlight = "minecraft:shroomlight";

  function stair(facing, half = "bottom") {
    if (stoneStairs.includes("[")) {
      return stoneStairs.replace(/facing=\w+/, `facing=${facing}`).replace(/half=\w+/, `half=${half}`);
    }
    return `${stoneStairs}[facing=${facing},half=${half},shape=straight]`;
  }
  function slab(type = "bottom") {
    if (stoneSlab.includes("[")) {
      return stoneSlab.replace(/type=\w+/, `type=${type}`);
    }
    return `${stoneSlab}[type=${type}]`;
  }

  // 3. Tube Path & Meander Parameters per instance
  const curveAmp = 1.3 + rng() * 2.1;
  const curveFreq = 0.85 + rng() * 0.55;
  const curvePhase = rng() * Math.PI * 2;
  const slant = (rng() - 0.5) * 0.3;
  const baseCenter = W * 0.5 + (rng() - 0.5) * 1.6;

  function getTubeCenter(z) {
    const normZ = z / (D - 1);
    return baseCenter + curveAmp * Math.sin(normZ * Math.PI * curveFreq + curvePhase) + slant * (z - D * 0.5);
  }

  const baseWidth = 6.8 + rng() * 1.6;
  function getTubeWidth(z) {
    const normZ = z / (D - 1);
    return baseWidth + 1.2 * Math.cos(normZ * Math.PI * 2 + curvePhase);
  }

  // 4. Skylight Collapse Mode & Features
  const mode = idx;
  let archZ1 = -1, archZ2 = -1;
  let islandX = -1, islandZ = -1;
  let hornitoX = -1, hornitoZ = -1;

  if (mode === 0) {
    archZ1 = 7;
  } else if (mode === 1) {
    archZ1 = 7;
    archZ2 = 8;
    hornitoX = Math.min(W - 2, Math.max(1, Math.floor(getTubeCenter(3) + 4.5)));
    hornitoZ = 3;
  } else if (mode === 3) {
    islandX = Math.floor(getTubeCenter(7));
    islandZ = 7;
  } else if (mode === 4) {
    archZ1 = 4;
    archZ2 = 11;
  } else if (mode === 5) {
    hornitoX = Math.min(W - 2, Math.max(1, Math.floor(getTubeCenter(12) - 4.5)));
    hornitoZ = 12;
  } else if (mode === 7) {
    hornitoX = Math.min(W - 2, Math.max(1, Math.floor(getTubeCenter(4) + 4.0)));
    hornitoZ = 4;
  }

  function isSkylight(x, z) {
    if (z <= 1 || z >= D - 2) return false;
    if (archZ1 >= 0 && Math.abs(z - archZ1) <= 0.5) return false;
    if (archZ2 >= 0 && Math.abs(z - archZ2) <= 0.5) return false;
    if (islandX >= 0 && Math.abs(x - islandX) <= 1 && Math.abs(z - islandZ) <= 1) return false;

    const cx = getTubeCenter(z);
    const hw = getTubeWidth(z) * (mode === 2 ? 0.56 : 0.46);
    const jag = 0.75 * Math.sin(x * 1.8 + z * 2.1) + 0.45 * Math.cos(z * 3.2 - x * 1.1);
    return Math.abs(x - cx) < (hw + jag);
  }

  // 5. Build Subterranean Lava Channel Bed (y = 0 to 2)
  for (let z = 0; z < D; z++) {
    const cx = getTubeCenter(z);
    const hw = getTubeWidth(z) * 0.5;

    for (let x = 0; x < W; x++) {
      const dist = Math.abs(x - cx);

      // Deep foundation floor
      set(x, 0, z, blackstone);

      if (dist < hw * 0.6) {
        // Active molten magma core
        const subR = rng();
        if (subR < 0.25) set(x, 1, z, shroomlight);
        else if (subR < 0.65) set(x, 1, z, magma);
        else set(x, 1, z, obsidian);

        const lavaR = rng();
        if (lavaR < 0.62) {
          set(x, 2, z, magma);
        } else if (lavaR < 0.82) {
          set(x, 2, z, cryingObsidian);
        } else if (lavaR < 0.94) {
          set(x, 2, z, obsidian);
        } else {
          set(x, 2, z, smoothBasalt);
        }
      } else if (dist <= hw) {
        // Cooled rock riverbanks
        set(x, 1, z, obsidian);
        const bankR = rng();
        if (bankR < 0.5) set(x, 2, z, smoothBasalt);
        else if (bankR < 0.8) set(x, 2, z, blackstone);
        else set(x, 2, z, obsidian);

        if (rng() < 0.35) {
          set(x, 3, z, slab("bottom"));
        }
      }
    }
  }

  // 6. Central Basalt Island (mode 3)
  if (islandX >= 0) {
    for (let ix = islandX - 1; ix <= islandX + 1; ix++) {
      for (let iz = islandZ - 1; iz <= islandZ + 1; iz++) {
        for (let iy = 1; iy <= 6; iy++) {
          set(ix, iy, iz, iy === 6 ? polishedBasalt : basaltY);
        }
        set(ix, 7, iz, slab("bottom"));
      }
    }
  }

  // 7. Cavern Sidewalls & Strata (y = 3 to 5)
  for (let z = 0; z < D; z++) {
    const cx = getTubeCenter(z);
    const hw = getTubeWidth(z) * 0.5;

    for (let x = 0; x < W; x++) {
      const dist = Math.abs(x - cx);

      for (let y = 3; y <= 5; y++) {
        const wallInner = hw * (0.62 + (y - 3) * 0.08);
        if (dist >= wallInner) {
          const r = rng();
          if (r < 0.45) set(x, y, z, basaltY);
          else if (r < 0.75) set(x, y, z, blackstone);
          else if (r < 0.9) set(x, y, z, smoothBasalt);
          else set(x, y, z, obsidian);
        }
      }
    }
  }

  // 8. Basalt Crust, Cantilevers & Broken Skylight (y = 6 to 8)
  for (let z = 0; z < D; z++) {
    const cx = getTubeCenter(z);
    const hw = getTubeWidth(z) * 0.5;

    for (let x = 0; x < W; x++) {
      const dist = Math.abs(x - cx);
      const collapsed = isSkylight(x, z);

      if (!collapsed) {
        // Intact volcanic roof crust
        const ceilR = rng();
        if (ceilR < 0.5) set(x, 6, z, basaltY);
        else if (ceilR < 0.8) set(x, 6, z, blackstone);
        else set(x, 6, z, smoothBasalt);

        // Surface layer with magma fissures
        const isFissure = (Math.sin(x * 1.5 + z * 2.7) > 0.65) && dist < hw + 2.5;
        if (isFissure) {
          set(x, 7, z, rng() < 0.7 ? magma : cryingObsidian);
        } else {
          const surfR = rng();
          if (surfR < 0.4) set(x, 7, z, blackstone);
          else if (surfR < 0.7) set(x, 7, z, smoothBasalt);
          else if (surfR < 0.9) set(x, 7, z, basaltY);
          else set(x, 7, z, scree);
        }

        // Pressure ridges & rock shelves
        const ridgeVal = Math.sin(x * 0.8 + z * 0.6 + curvePhase);
        if (ridgeVal > 0.55 && dist > hw * 0.6) {
          if (rng() < 0.5) set(x, 8, z, slab("bottom"));
          else set(x, 8, z, scree);
        }
      } else {
        // Open Skylight!
        if (dist >= hw * 0.9) {
          set(x, 6, z, basaltY);
          set(x, 7, z, blackstone);
          if (rng() < 0.3) set(x, 8, z, slab("bottom"));
        } else if (dist >= hw * 0.5) {
          // Cantilevered rock slabs projecting over the void
          const facing = x < cx ? "east" : "west";
          const logAxis = Math.abs(x - cx) > 1 ? basaltX : basaltZ;

          if (rng() < 0.5) {
            set(x, 6, z, logAxis);
            set(x, 7, z, stair(facing, "bottom"));
          } else if (rng() < 0.75) {
            set(x, 6, z, stair(facing, "top"));
            set(x, 7, z, slab("bottom"));
          } else {
            set(x, 6, z, slab("top"));
            set(x, 7, z, blackstone);
          }

          // Fractured cantilever eave steps
          if (rng() < 0.35) {
            const stepX = x < cx ? x + 1 : x - 1;
            if (isSkylight(stepX, z) && !has(stepX, 6, z)) {
              set(stepX, 6, z, slab("top"));
              if (rng() < 0.4) set(stepX, 7, z, stoneWall);
            }
          }
        }
      }
    }
  }

  // 9. Natural Stone Arches Spanning the Skylight
  const archList = [];
  if (archZ1 >= 0) archList.push(archZ1);
  if (archZ2 >= 0) archList.push(archZ2);

  for (const az of archList) {
    const cx = Math.round(getTubeCenter(az));
    const hw = Math.round(getTubeWidth(az) * 0.45);

    for (let x = cx - hw; x <= cx + hw; x++) {
      if (x < 1 || x >= W - 1) continue;
      const isCenter = Math.abs(x - cx) <= 1;
      const facing = x < cx ? "east" : "west";

      if (isCenter) {
        set(x, 5, az, smoothBasalt);
      } else {
        set(x, 5, az, stair(facing, "top"));
      }

      set(x, 6, az, basaltX);
      set(x, 7, az, isCenter ? blackstone : slab("bottom"));

      if (rng() < 0.4) {
        set(x, 8, az, stoneWall);
      }
    }
  }

  // 10. Fallen Basalt Boulders in the Trench
  const numBoulders = 3 + Math.floor(rng() * 4);
  for (let b = 0; b < numBoulders; b++) {
    const bz = 2 + Math.floor(rng() * (D - 4));
    const bcx = getTubeCenter(bz);
    const bx = Math.floor(bcx + (rng() - 0.5) * 3.5);

    if (bx >= 1 && bx < W - 1 && isSkylight(bx, bz)) {
      set(bx, 2, bz, obsidian);
      set(bx, 3, bz, rng() < 0.6 ? blackstone : basaltY);
      if (rng() < 0.6) {
        set(bx, 4, bz, slab("bottom"));
      }
    }
  }

  // 11. Volcanic Spatter Cone / Hornito Fumarole
  if (hornitoX >= 1 && hornitoX < W - 1 && hornitoZ >= 1 && hornitoZ < D - 1) {
    set(hornitoX, 7, hornitoZ, magma);
    set(hornitoX, 8, hornitoZ, magma);
    set(hornitoX, 9, hornitoZ, cryingObsidian);

    const neighbors = [
      [1, 0, "west"],
      [-1, 0, "east"],
      [0, 1, "north"],
      [0, -1, "south"]
    ];
    for (const [dx, dz, fac] of neighbors) {
      const nx = hornitoX + dx;
      const nz = hornitoZ + dz;
      if (nx >= 0 && nx < W && nz >= 0 && nz < D) {
        set(nx, 7, nz, blackstone);
        set(nx, 8, nz, stair(fac, "bottom"));
        if (rng() < 0.7) {
          set(nx, 9, nz, stoneWall);
        }
      }
    }
  }

  // 12. Ground Conformance & Skirt (Rule 6)
  for (let z = 0; z < D; z++) {
    for (let x = 0; x < W; x++) {
      let minY = H;
      let maxY = -1;
      for (let y = 0; y < H; y++) {
        if (has(x, y, z)) {
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
        }
      }

      if (maxY >= 0) {
        const h = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(H - 1, seatY + h));
        const targetMin = Math.min(minY, groundY, 1);

        for (let y = targetMin; y < minY; y++) {
          set(x, y, z, y <= 1 ? blackstone : basaltY);
        }

        if (groundY > maxY) {
          for (let y = maxY + 1; y <= groundY; y++) {
            set(x, y, z, y === groundY ? smoothBasalt : blackstone);
          }
        }
      }
    }
  }

  // Emit all placed blocks
  for (const [k, block] of grid.entries()) {
    const [sx, sy, sz] = k.split(",").map(Number);
    api.set(sx, sy, sz, block);
  }

  return {
    name: "collapsed_lava_tube",
    seatY: seatY,
    anchors: {
      front: [Math.floor(W / 2), seatY, 0],
      skylight: [Math.floor(W / 2), seatY + 3, Math.floor(D / 2)]
    }
  };
}
